// Java 25: Mekanizmadan Bağımsız Davranışsal Test (Tests Carry the Truth)
package com.maang.aiup.principles;

public class ObservableBehaviorTest {
    // Sözleşme: Parola formatı doğrulanır (Mekanizma: regex mi değil mi şartnameye yazılmaz!)
    public interface PasswordValidator {
        boolean isValid(String password);
    }

    // İlke 14: Gerçeği taşıyan test paketi
    public static void runTests(PasswordValidator validator) {
        // Test 1: En az 8 karakter olmalı
        assert !validator.isValid("short") : "8 karakterden kısa parola reddedilmeli!";
        // Test 2: Rakam içermeli
        assert !validator.isValid("NoDigitsHere!") : "Rakam içermeyen parola reddedilmeli!";
        // Test 3: Başarılı parola
        assert validator.isValid("SecureP@ss2026") : "Geçerli parola kabul edilmeli!";

        System.out.println("✅ İlke 14: Tüm davranışsal testler başarıyla geçti!");
    }

    void main() {
        // AI'ın ürettiği implementasyon (İster regex kullansın, ister döngü!)
        PasswordValidator aiGenerated = pwd -> pwd != null && pwd.length() >= 8 && pwd.matches(".*\d.*");
        runTests(aiGenerated);
    }
}

// Java 25: Şartname Değişikliğinin Koddaki Yansıması (Regeneration Friendly)
package com.maang.aiup.principles;

public class LoanInterestCalculation {
    // ESKİ KURAL BR-012: Faiz oranı sabit %5.0 idi.
    // YENİ KURAL BR-012 (Değişiklik Şartnamede Yapıldı): VIP üyeler için faiz %3.5, diğerleri %5.0.

    public record Customer(String id, boolean isVip) {}

    public static double calculateInterestRate(Customer customer) {
        // Şartnamedeki BR-012 güncellemesinden sonra AI tarafından üretilen yeni kod:
        if (customer.isVip()) {
            return 3.5; // BR-012 (Revize edilmiş şartname kuralı)
        }
        return 5.0;     // BR-012 Standart kural
    }

    void main() {
        var vip = new Customer("VIP-1", true);
        var standard = new Customer("STD-2", false);

        System.out.println("VIP Faiz: %" + calculateInterestRate(vip));
        System.out.println("Standart Faiz: %" + calculateInterestRate(standard));
    }
}

// Java 25: Aktör Rollerini Güvenlik ve Yetkilendirme Modeline Dönüştürme
package com.maang.aiup.actors;

public class ActorSecurityModel {
    // Şartnamede tanımlanan roller doğrudan Java 25 Enum/Record ile modellenir
    public enum SystemRole {
        MEMBER, LIBRARIAN, SYSTEM_ADMIN
    }

    public record SecurityContext(String userId, SystemRole role) {
        public void requireRole(SystemRole requiredRole) {
            if (this.role != requiredRole) {
                throw new SecurityException("Erişim reddedildi: Bu işlem için " + requiredRole + " rolü zorunludur.");
            }
        }
    }

    // Birincil Aktör: Member
    public static void borrowBook(SecurityContext context, String bookId) {
        context.requireRole(SystemRole.MEMBER);
        System.out.println("Üye yetkisi doğrulandı, işlem başlıyor: " + bookId);
    }

    void main() {
        var memberCtx = new SecurityContext("user-42", SystemRole.MEMBER);
        borrowBook(memberCtx, "BOOK-1984");
    }
}

// Java 25: Üç Adımlı Testin Mimarideki Birebir Karşılığı
package com.maang.aiup.stepkinds;

public class ThreeStepTestService {
    // Domain State
    public record BookCopy(String id, boolean isAvailable) {}
    public record LoanRecord(String loanId, String memberId, String copyId, java.time.LocalDate dueDate) {}

    public LoanRecord executeBorrowProcess(String memberId, BookCopy copy) {
        // TÜR 1: Etkileşim (Girdi parametreleri olarak geldi: memberId ve copy)

        // TÜR 2: DOĞRULAMA (Validation - Stakeholder Interest)
        if (!copy.isAvailable()) {
            throw new IllegalStateException("BR-004: Kitap kopyası ödünç verilebilir durumda değil!");
        }

        // TÜR 3: DURUM DEĞİŞİMİ (Internal State Change)
        var updatedCopy = new BookCopy(copy.id(), false); // Stok azaldı
        var loan = new LoanRecord("L-99", memberId, updatedCopy.id(), java.time.LocalDate.now().plusDays(28));

        System.out.println("✅ 3 Adımlı Test Tamamlandı: " + loan);
        return loan;
    }

    void main() {
        var service = new ThreeStepTestService();
        service.executeBorrowProcess("MEM-1", new BookCopy("CPY-1", true));
    }
}

